<?php require_once __DIR__.'/../../app/layout.php';require_once __DIR__.'/../../app/payment_reporting.php';$a=require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];if(($_POST['action']??'')==='send_member_request'){$p=$pdo->prepare('SELECT donor_name,donor_email,member_id FROM donations WHERE id=?');$p->execute([$id]);$guest=$p->fetch();if($guest&&$guest['member_id']===null&&filter_var($guest['donor_email'],FILTER_VALIDATE_EMAIL)){$url=rtrim(env('APP_URL','https://tssmt.org'),'/').'/register.php';$name=e($guest['donor_name']?:'Supporter');$sent=org_send_mail($guest['donor_email'],'Join '.setting($pdo,'org_name','TSSMT'),'<p>Dear '.$name.',</p><p>Thank you for supporting '.e(setting($pdo,'org_name','TSSMT')).'. We invite you to become a member.</p><p><a href="'.e($url).'">Submit your membership request</a></p>');if($sent){audit($pdo,$a['id'],'guest_membership_request_sent','donation',$id);flash('Membership request email sent.');}else flash('Unable to send the email. Check the guest email address and SMTP settings.','error');}else flash('This donation is not an eligible guest record with an email address.','error');redirect('/admin/donations.php?range='.rawurlencode((string)($_POST['range']??'this_month')));}$status=$_POST['action']==='approve'?'approved':'rejected';$pdo->prepare('UPDATE donations SET status=?,approved_by=?,approved_at=NOW(),remarks=? WHERE id=? AND status="pending"')->execute([$status,$a['id'],trim($_POST['remarks']??''),$id]);if($status==='approved'){$p=$pdo->prepare('SELECT member_id,amount FROM donations WHERE id=?');$p->execute([$id]);$r=$p->fetch();if($r&&$r['member_id'])$pdo->prepare('INSERT IGNORE INTO acknowledgements (acknowledgement_no,member_id,payment_type,source_id,amount,issued_at) VALUES (?,?,?,?,?,NOW())')->execute(['DON/'.date('Y').'/'.str_pad((string)$id,6,'0',STR_PAD_LEFT),$r['member_id'],'donation',$id,$r['amount']]);}audit($pdo,$a['id'],'donation_'.$status,'donation',$id);flash('Donation '.$status.'.');redirect('/admin/donations.php?range='.rawurlencode((string)($_POST['range']??'this_month')));}
$range=payment_date_range($_GET['range']??null);$sql="SELECT d.*,COALESCE(m.full_name,d.donor_name) AS donor,COALESCE(mt.name,'Guest') AS member_type,COALESCE(m.district,d.donor_city) AS city,COALESCE(m.mobile,d.donor_mobile) AS mobile FROM donations d LEFT JOIN members m ON m.id=d.member_id LEFT JOIN membership_types mt ON mt.id=m.membership_type_id";$rows=payment_range_query($pdo,$sql,$range,'ORDER BY d.payment_date DESC, d.created_at DESC');if(($_GET['export']??'')==='excel')export_excel_xml('donations-'.$range['key'],['Date of Donation','Donor','Member Type / Guest','City','Mobile','Purpose','Amount','Transaction','Status'],array_map(static fn(array $r):array=>[$r['payment_date'],$r['donor'],$r['member_type'],$r['city'],$r['mobile'],$r['purpose'],$r['amount'],$r['transaction_no'],$r['status']],$rows));header_html('Donations');?>
<style>body:has(.donations-table) main{max-width:1500px}.donations-table{table-layout:auto;white-space:nowrap}.donations-table td:first-child{min-width:125px;white-space:normal}.reporting-filter{display:flex;align-items:end;gap:12px;margin:0;padding:0;background:transparent;border:0;box-shadow:none}.reporting-filter label{margin:0}.reporting-filter select{margin:5px 0 0}.guest-request{margin-top:6px!important;padding:7px 9px!important;font-size:.85rem}</style><h1>Donations</h1><?php payment_range_filter($range);?><table class="donations-table"><tr><th>Date of Donation</th><th>Donor</th><th>Member Type</th><th>City</th><th>Mobile No</th><th>Purpose</th><th>Amount</th><th>Transaction</th><th>Status</th><th>Verify</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['payment_date'])?></td><td><?=e($r['donor'])?></td><td><?=e($r['member_type'])?></td><td><?=e((string)$r['city'])?></td><td><?=e((string)$r['mobile'])?></td><td><?=e($r['purpose'])?></td><td>₹<?=e($r['amount'])?></td><td><?=e((string)$r['transaction_no'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="range" value="<?=e($range['key'])?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="remarks" placeholder="Remarks"><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?><?php if($r['member_type']==='Guest'&&$r['member_id']===null&&!empty($r['donor_email'])):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="range" value="<?=e($range['key'])?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="guest-request" name="action" value="send_member_request">Send member request</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php footer_html();
